using System;
using System.Drawing;
using System.IO;
using System.Windows.Forms;
using Prometheus;

class SubtitleViewTests0820 {
 [STAThread] static void Main(string[] args){Application.EnableVisualStyles();var project=Store.New();SubtitleTrack0817.Add(project,"Hola mundo",0,1);SubtitleAnimation0820.Set(project.Active,File.ReadAllText(args[0]));var form=new Form{Width=720,Height=450,Text="Prueba de subtítulos MGT",ShowInTaskbar=false};var canvas=new PreviewCanvas{Dock=DockStyle.Fill,CanvasWidth=1920,CanvasHeight=1080};form.Controls.Add(canvas);var overlay=new MgtSubtitleView0820(canvas);string error=null;bool ready=false,opaque=false,transparent=false;overlay.Failed=message=>{error=message;form.Close();};overlay.ReadyChanged=async()=>{if(!overlay.Ready)return;ready=true;overlay.SetFrame(.5);await System.Threading.Tasks.Task.Delay(500);try{var field=typeof(MgtSubtitleView0820).GetField("view",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);var web=(Microsoft.Web.WebView2.WinForms.WebView2)field.GetValue(overlay);using(var memory=new MemoryStream()){await web.CoreWebView2.CapturePreviewAsync(Microsoft.Web.WebView2.Core.CoreWebView2CapturePreviewImageFormat.Png,memory);memory.Position=0;using(var image=new Bitmap(memory))for(int y=0;y<image.Height;y+=4)for(int x=0;x<image.Width;x+=4){int alpha=image.GetPixel(x,y).A;if(alpha>0)opaque=true;if(alpha==0)transparent=true;}}overlay.SetPreviewEnabled(false);if(overlay.Ready||SubtitleAnimation0820.PreviewOverlayReady)throw new Exception("El ojo no ocultó la capa MGT");overlay.SetPreviewEnabled(true);if(!overlay.Ready||!SubtitleAnimation0820.PreviewOverlayReady)throw new Exception("El ojo no restauró la capa MGT");}catch(Exception ex){error=ex.Message;}form.Close();};var timer=new Timer{Interval=15000};timer.Tick+=(s,e)=>{timer.Stop();form.Close();};form.Shown+=(s,e)=>{timer.Start();overlay.SetProject(project,.5);};Application.Run(form);timer.Dispose();overlay.Dispose();if(!ready||!opaque||!transparent)throw new Exception(error??"La vista MGT no preservó los píxeles transparentes y visibles");Console.WriteLine("OK: WebView2 local con píxeles transparentes y animados");}
}
